from pathlib import Path
import json
puzzles=json.loads(Path('puzzles-data.json').read_text());meta=json.loads(Path('puzzles-build.json').read_text()) if Path('puzzles-build.json').exists() else {}
engine=Path('chess-engine.js').read_text().split('export {')[0]
html='''<!doctype html><html lang="he" dir="rtl"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>חידות השחמט שלך</title><style>*{box-sizing:border-box}body{margin:0;background:#292b26;color:#efeee5;font:16px system-ui;line-height:1.65}header{max-width:1200px;margin:auto;padding:20px 24px;display:flex;align-items:center;justify-content:space-between;gap:15px}h1{font-size:25px;margin:0}a{color:#c6dfa4}small,.muted{color:#b9beb0}main{max-width:1200px;margin:auto;padding:0 24px 24px;display:grid;grid-template-columns:minmax(0,1fr) 340px;gap:24px}.game{width:min(100%,calc(100vh - 360px));justify-self:center}.bar{display:flex;justify-content:space-between;gap:10px;padding:10px 0}.chip{padding:4px 12px;background:#3a4032;border-radius:20px;font-size:14px;color:#d5e5bf}#board{display:grid;grid-template-columns:repeat(8,1fr);direction:ltr;border-radius:7px;overflow:hidden;width:100%;aspect-ratio:1}#board button{aspect-ratio:1;position:relative;padding:0;border:0;border-radius:0;display:grid;place-items:center;background:var(--square);min-width:0;min-height:0}.light{--square:#eeeed2;--label:#769656}.dark{--square:#769656;--label:#eeeed2}#board img{width:91%;height:91%;pointer-events:none;filter:drop-shadow(0 1px 1px #0003)}#board .selected{background:#f1ed69}#board .last{background:#bbce58}#board .possible:after{content:'';width:24%;height:24%;position:absolute;background:#0003;border-radius:50%;pointer-events:none}.coord{position:absolute;font-size:clamp(11px,1.5vw,20px);font-weight:bold;color:var(--label)}.rank{top:1px;left:4px}.file{bottom:0;right:4px}button,select{min-height:44px;border:1px solid #ffffff12;border-radius:7px;padding:10px 12px;font:inherit;color:#f3f1e8;background:#444b3b;cursor:pointer}button:hover{filter:brightness(1.1)}button:focus-visible,select:focus-visible{outline:3px solid #e7c976;outline-offset:2px}#board button:focus-visible{outline-offset:-3px}button:disabled{opacity:.4;cursor:default}aside{background:#33362e;padding:22px;border-radius:12px;max-height:calc(100vh - 110px);overflow:auto}.filters{display:grid;gap:10px}label{font-size:14px}select{width:100%;display:block}.row{display:flex;gap:8px;margin-top:12px}.row button{flex:1}#next{background:#7fa44d;color:white;font-weight:bold}.feedback{padding:13px;border-radius:8px;background:#22291d;margin:15px 0;color:#d2e9b6;min-height:65px}.feedback.error{background:#492f27;color:#ffe3c8}h2{font-size:18px;margin:20px 0 8px}.stats{display:grid;grid-template-columns:repeat(3,1fr);gap:6px;text-align:center;font-size:12px}.stats b{display:block;font-size:23px;color:#d5e5bf}.source{font-size:13px;color:#bfc4b6;border-top:1px solid #ffffff18;padding-top:12px}#line{direction:ltr;word-spacing:5px;line-height:2}.note{font-size:12px;line-height:1.7}details{margin-top:18px}summary{cursor:pointer}.progress{height:5px;background:#444b3b;border-radius:5px;overflow:hidden}.progress div{height:100%;background:#93b96a}.boardbuttons{display:flex;gap:8px}.boardbuttons button{flex:1}@media(max-width:850px){header{padding:14px;display:block}header nav{margin-top:5px}main{grid-template-columns:1fr;padding:0 12px 18px;gap:15px}.game{width:min(100%,calc(100vh - 350px))}aside{max-height:none}.coord{font-size:clamp(11px,3vw,20px)}}@media(prefers-reduced-motion:reduce){*{scroll-behavior:auto}}</style><header><div><h1>חידות מתוך המשחקים שלך</h1><small id="total"></small></div><nav><a href="chess.html">משחק</a> · <a href="insights.html">דוח שיפור</a></nav></header><main><section class="game"><div class="bar"><b id="turn"></b><span class="chip" id="topic"></span></div><div id="board" aria-label="לוח חידת שחמט"></div><div class="bar"><span id="number"></span><span id="hardness"></span></div><div class="progress"><div id="progressFill"></div></div><div class="row boardbuttons"><button id="next">החידה הבאה</button><button id="flip">סיבוב הלוח</button><button id="restart">נסה שוב</button></div><p class="muted" style="font-size:14px">בחר כלי ואז משבצת. המטרה היא למצוא את המהלך הראשון הטוב ביותר.</p></section><aside><div class="filters"><label>מסלול<select id="track"><option value="recommended">מותאם לי</option><option value="all">כל המאגר</option><option value="originalErrors">טעויות מהמשחקים המקוריים</option><option value="mistakes">חזרה על טעויות שלי בחידות</option><option value="unseen">חידות שטרם פתרתי</option><option value="opening">פתיחה והגנת המלך</option></select></label><label>נושא<select id="theme"><option value="all">כל הנושאים</option></select></label><label>קושי<select id="difficulty"><option value="adaptive">מותאם לפי התרגול שלי</option><option value="all">כל הרמות</option><option>קל</option><option>בינוני</option><option>מאתגר</option></select></label></div><div id="feedback" class="feedback" aria-live="polite"></div><div class="row"><button id="hint">רמז</button><button id="reveal">פתרון</button></div><h2>התרגול שלך</h2><div class="stats"><div><b id="solvedCount">0</b>נפתרו</div><div><b id="cleanCount">0</b>ללא עזרה</div><div><b id="successRate">—</b>הצלחה בניסיון ראשון</div></div><p id="adaptiveNote" class="note muted"></p><section id="solution" hidden><h2>המהלך וההמשך</h2><p id="explanation"></p><p id="line"></p><div class="row"><button id="linePrev">קודם</button><button id="lineNext">המשך</button></div><p class="note muted">ההמשך הוא קו שהמנוע הציע, ולא תגובה יחידה שהיריב חייב לשחק.</p></section><p class="source" id="source"></p><details><summary>איך הותאם המאגר?</summary><p class="note">כל החידות הגיעו מעמדות שלך מול אנשים ב־Chess.com. הדגש הוא על פתיחה, בטיחות המלך ומהלכים טקטיים עם שח או הכאה. בחלק מהעמדות כבר מצאת את המהלך במשחק המקורי — זה תרגול לשימור מיומנות.</p><p class="note">הקושי הוא הערכה מקומית, לא דירוג Chess.com. התאמת הקושי מבוססת על הצלחות ללא רמזים; טעויות חוזרות מקבלות עדיפות. הנתונים נשמרים במכשיר ומסתנכרנים לאחר כניסה עם Google.</p><p class="note" id="verification"></p><p class="note"><a href="puzzles-data.json">הורדת המאגר</a> · <a href="https://github.com/nmrugg/stockfish.js">Stockfish 10</a> · כלים: Cburnett, CC BY-SA 3.0.</p></details></aside></main><script>'''
js=r'''
const puzzles=__DATA__,meta=__META__,names={p:'רגלי',n:'פרש',b:'רץ',r:'צריח',q:'מלכה',k:'מלך'},$=id=>document.getElementById(id);let progress={records:{},tier:0,streak:0};try{const saved=JSON.parse(localStorage.getItem('personal-puzzles-v1'));if(saved&&saved.records)progress=saved}catch{}let current=null,position=null,selected=null,flipped=false,finished=false,attempts=0,hints=0,viewStep=0,last=null,sessionSeen=new Set();
function save(){progress.updatedAt=Date.now();try{localStorage.setItem('personal-puzzles-v1',JSON.stringify(progress))}catch{}stats();window.chessSyncChanged?.()}
function stats(){const records=Object.values(progress.records),solved=records.filter(x=>x.solved),attempted=records.filter(x=>x.attempted);$('solvedCount').textContent=solved.length;$('cleanCount').textContent=records.filter(x=>x.clean).length;$('successRate').textContent=attempted.length?Math.round(100*records.filter(x=>x.firstClean).length/attempted.length)+'%':'—';$('adaptiveNote').textContent='הרמה המותאמת כרגע: '+['קל','בינוני','מאתגר'][progress.tier]+'. שלוש הצלחות רצופות ללא עזרה מעלות קושי. שתי חידות עם טעויות מורידות קושי.';$('progressFill').style.width=(100*solved.length/puzzles.length)+'%'}
function renderBoard(){const board=$('board');board.innerHTML='';const legal=!finished&&selected?position.moves({square:selected,verbose:true}):[];const ranks=flipped?[1,2,3,4,5,6,7,8]:[8,7,6,5,4,3,2,1],files=flipped?'hgfedcba':'abcdefgh';for(const [ri,r]of ranks.entries())for(const [fi,f]of [...files].entries()){const sq=f+r,p=position.get(sq),b=document.createElement('button');b.className=((r+'abcdefgh'.indexOf(f))%2?'light':'dark')+(selected===sq?' selected':'')+(last&&(last.from===sq||last.to===sq)?' last':'')+(legal.some(m=>m.to===sq)?' possible':'');b.setAttribute('aria-label',sq+(p?' '+names[p.type]+' '+(p.color==='w'?'לבן':'שחור'):''));if(p){const img=document.createElement('img');img.src='pieces/'+p.color+p.type.toUpperCase()+'.svg';img.alt='';b.append(img)}if(fi===0){const span=document.createElement('span');span.className='coord rank';span.textContent=r;b.append(span)}if(ri===7){const span=document.createElement('span');span.className='coord file';span.textContent=f;b.append(span)}b.onclick=()=>play(sq);board.append(b)}}
function feedback(text,error=false){$('feedback').textContent=text;$('feedback').className='feedback'+(error?' error':'')}
function filtered(){return puzzles.filter(p=>($('theme').value==='all'||p.theme===$('theme').value)&&($('difficulty').value==='all'||$('difficulty').value==='adaptive'||p.difficulty===$('difficulty').value)&&($('track').value!=='mistakes'||(progress.records[p.id]?.wrong||0)>0)&&($('track').value!=='unseen'||!progress.records[p.id]?.solved)&&($('track').value!=='opening'||p.opening)&&($('track').value!=='originalErrors'||!p.originalCorrect))}
function next(){const pool=filtered();if(!pool.length){feedback('אין חידות במסננים האלה. בחר נושא או מסלול אחר.');return}let desired=['קל','בינוני','מאתגר'][progress.tier],eligible=$('difficulty').value==='adaptive'?pool.filter(p=>p.difficulty===desired):pool;if(!eligible.length)eligible=pool;let fresh=eligible.filter(p=>!sessionSeen.has(p.id));if(fresh.length)eligible=fresh;const rated=eligible.map(p=>{const r=progress.records[p.id]||{};return {p,score:Math.random()*2+(r.wrong&&!r.clean?4:0)+(!r.solved?2:0)+($('track').value==='recommended'&&(p.opening||p.theme.includes('מט'))?2:0)+($('track').value==='recommended'&&!p.originalCorrect?5:0)}}).sort((a,b)=>b.score-a.score);current=rated[0].p;sessionSeen.add(current.id);start()}
function start(){position=new Chess(current.fen);selected=null;flipped=current.color==='b';finished=false;attempts=0;hints=0;viewStep=0;last=null;$('solution').hidden=true;$('hint').disabled=false;$('reveal').disabled=false;$('turn').textContent=(current.color==='w'?'לבן':'שחור')+' משחק';$('topic').textContent=current.theme;$('hardness').textContent=current.difficulty;$('number').textContent='חידה '+current.id.slice(1)+' / '+puzzles.length;$('source').textContent=current.date+' · מול '+current.opponent+' · מסע '+current.move;feedback(current.theme==='מט במסע אחד'?'מצא מט במסע אחד.':position.isCheck()?'המלך שלך בשח. מצא את התגובה הטובה ביותר.':'מצא את המהלך הטקטי הטוב ביותר. בדוק שח והכאות לפני שתבחר.');renderBoard();stats()}
function recordResult(clean){const r=progress.records[current.id]??={};r.attempted=true;r.solved=true;if(r.firstClean===undefined)r.firstClean=clean;r.clean=!!r.clean||clean;r.lastSolved=Date.now();if(clean){progress.streak++;progress.errorStreak=0;if(progress.streak>=3){progress.tier=Math.min(2,progress.tier+1);progress.streak=0}}else{progress.streak=0;progress.errorStreak=(progress.errorStreak||0)+1;if(progress.errorStreak>=2){progress.tier=Math.max(0,progress.tier-1);progress.errorStreak=0}}save()}
function play(sq){if(finished)return;const piece=position.get(sq);if(piece&&piece.color===position.turn()){selected=sq;renderBoard();return}if(!selected)return;let m;try{m=position.move({from:selected,to:sq,promotion:'q'})}catch{selected=null;feedback('המהלך אינו חוקי. בחר כלי ומשבצת מחדש.',true);renderBoard();return}attempts++;const accepted=current.acceptSans.includes(m.san);if(accepted){finished=true;last=m;selected=null;recordResult(attempts===1&&hints===0);feedback(hints?'נכון! עכשיו חזור על העמדה ללא רמז.':'נכון! מצאת את המהלך.');showSolution();renderBoard()}else{position.undo();selected=null;const r=progress.records[current.id]??={};r.wrong=(r.wrong||0)+1;r.attempted=true;if(r.firstClean===undefined)r.firstClean=false;save();feedback('זה מהלך חוקי, אבל יש מהלך טוב יותר לפי הניתוח. בדוק שוב שח, הכאות ואיומים.',true);renderBoard()}}
function showSolution(){const p=current;$('solution').hidden=false;$('hint').disabled=true;$('reveal').disabled=true;$('line').textContent=p.line.join(' → ');$('explanation').textContent='המהלך המומלץ: '+p.san+'. '+(p.theme==='מט במסע אחד'?'המלך בשח ואין ליריב מהלך חוקי שמוציא אותו מהשח.':p.mate?'המנוע מצא מסלול למט במשחק מיטבי. בחן את תגובות היריב בהמשך.':p.captured?'המהלך מכה '+names[p.captured]+'. ההמשך מדגים למה ההכאה עדיפה על החלופות שנבדקו.':'השח מחייב את היריב להגיב. בדוק מה משתנה אחרי התגובה המוצעת.')+' במשחק המקורי שיחקת '+p.played+(p.originalCorrect?' — כבר מצאת אז את ההמלצה.':'.');viewStep=1;updateLineButtons()}
function updateLineButtons(){$('linePrev').disabled=viewStep===0;$('lineNext').disabled=viewStep>=current.line.length}
function viewLine(step){viewStep=Math.max(0,Math.min(current.line.length,step));position=new Chess(current.fen);last=null;for(const san of current.line.slice(0,viewStep))last=position.move(san);selected=null;renderBoard();updateLineButtons()}
$('hint').onclick=()=>{if(!current||finished)return;hints++;const origin=current.solution.slice(0,2),dest=current.solution.slice(2,4);feedback(hints===1?(current.theme.includes('מט')?'בדוק את כל השחים האפשריים והאם למלך יש משבצת בריחה.':current.captured?'בדוק הכאות אפשריות וחשב את תגובת היריב.':'בדוק אילו כלים יכולים לתת שח ומה הם מאיימים אחריו.'):hints===2?'התמקד ב'+names[current.piece]+' שבמשבצת '+origin+'.':'נסה להעביר את הכלי מ־'+origin+' ל־'+dest+'.')};
$('reveal').onclick=()=>{if(!current||finished)return;finished=true;hints++;const r=progress.records[current.id]??={};r.revealed=(r.revealed||0)+1;r.wrong=(r.wrong||0)+1;r.attempted=true;if(r.firstClean===undefined)r.firstClean=false;progress.streak=0;progress.errorStreak=(progress.errorStreak||0)+1;if(progress.errorStreak>=2){progress.tier=Math.max(0,progress.tier-1);progress.errorStreak=0}save();showSolution();viewLine(1);feedback('הפתרון מוצג. חזור על החידה מאוחר יותר כדי לתרגל בעצמך.')};$('restart').onclick=()=>{if(current)start()};$('flip').onclick=()=>{flipped=!flipped;renderBoard()};$('next').onclick=next;$('linePrev').onclick=()=>viewLine(viewStep-1);$('lineNext').onclick=()=>viewLine(viewStep+1);for(const id of ['track','theme','difficulty'])$(id).onchange=next;for(const theme of [...new Set(puzzles.map(p=>p.theme))]){const o=document.createElement('option');o.value=theme;o.textContent=theme;$('theme').append(o)}$('total').textContent=puzzles.length+' חידות אישיות · סנכרון עם Google · ללא מנוי';$('verification').textContent='כל עמדה נבדקה בשני חיפושי מנוע, עם עומק אימות של לפחות 9. לחידות שאינן מט מיידי נדרש יתרון של לפחות 1.3 רגלים על החלופה השנייה. כל המהלכים והקווים נבדקו כחוקיים. אימות זה מוגבל לעומק החיפוש ואינו הוכחה מתמטית למהלך יחיד. במט מיידי מתקבלים כל מהלכי המט החוקיים.';next();
'''
Path('puzzles.html').write_text(html+engine+js.replace('__DATA__',json.dumps(puzzles,ensure_ascii=False)).replace('__META__',json.dumps(meta))+'</script><script src="sync-core.js?v=2"></script><script src="sync.js?v=2"></script></html>')
